let audioCtx = null
const ALLEZ_SOCHAUX_B64 = ''
let allezSochauxBuffer = null

function getCtx() {
  if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)()
  return audioCtx
}

async function getAllezSochauxBuffer() {
  if (allezSochauxBuffer) return allezSochauxBuffer
  try {
    const ctx = getCtx()
    const binary = atob(ALLEZ_SOCHAUX_B64)
    const bytes = new Uint8Array(binary.length)
    for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i)
    allezSochauxBuffer = await ctx.decodeAudioData(bytes.buffer)
    return allezSochauxBuffer
  } catch(e) { console.error('Audio decode failed:', e); return null }
}

export async function playAllezSochaux() {
  try {
    const ctx = getCtx()
    const buffer = await getAllezSochauxBuffer()
    if (!buffer) return
    const source = ctx.createBufferSource()
    source.buffer = buffer
    source.connect(ctx.destination)
    source.start(0)
  } catch(e) { console.error('Play failed:', e) }
}

function playTone(freq, type = 'sine', duration = 0.1, vol = 0.3, delay = 0) {
  try {
    const ctx = getCtx()
    const osc = ctx.createOscillator()
    const gain = ctx.createGain()
    osc.connect(gain)
    gain.connect(ctx.destination)
    osc.type = type
    osc.frequency.value = freq
    const t = ctx.currentTime + delay
    gain.gain.setValueAtTime(vol, t)
    gain.gain.exponentialRampToValueAtTime(0.001, t + duration)
    osc.start(t)
    osc.stop(t + duration)
  } catch(e) {}
}

export function playAdd() {
  playAllezSochaux()
}

export function playDelete() {
  playTone(300, 'sine', 0.08, 0.2, 0)
  playTone(200, 'sine', 0.1, 0.15, 0.08)
}

export function playNav() {
  playTone(880, 'sine', 0.06, 0.08, 0)
}

export function playTick(freq = 700) {
  playTone(freq, 'square', 0.06, 0.12, 0)
}

export function playWin() {
  playAllezSochaux()
}

export function vibrate(pattern = [10]) {
  try { navigator.vibrate?.(pattern) } catch(e) {}
}
